// Differential checks of InlineDemo.js against Lean, generated by leanscript --check
import * as M from "./InlineDemo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("foo(0n, 0n)", () => M.foo(0n, 0n), "0", false);
check("foo(0n, 2n)", () => M.foo(0n, 2n), "0", false);
check("foo(1n, 1n)", () => M.foo(1n, 1n), "2", false);
check("foo(2n, 0n)", () => M.foo(2n, 0n), "2", false);
check("foo(0n, 13n)", () => M.foo(0n, 13n), "0", false);
check("foo(1n, 5n)", () => M.foo(1n, 5n), "6", false);
check("foo(2n, 2n)", () => M.foo(2n, 2n), "6", false);
check("foo(5n, 1n)", () => M.foo(5n, 1n), "10", false);
check("foo(13n, 0n)", () => M.foo(13n, 0n), "13", false);
check("foo(2n, 13n)", () => M.foo(2n, 13n), "28", false);
check("foo(5n, 5n)", () => M.foo(5n, 5n), "30", false);
check("foo(13n, 2n)", () => M.foo(13n, 2n), "39", false);
check("foo(13n, 13n)", () => M.foo(13n, 13n), "182", false);
check("bar()", () => M.bar(), "3", false);
check("useScale(0n)", () => M.useScale(0n), "2", false);
check("useScale(1n)", () => M.useScale(1n), "6", false);
check("useScale(2n)", () => M.useScale(2n), "10", false);
check("useScale(5n)", () => M.useScale(5n), "22", false);
check("useScale(13n)", () => M.useScale(13n), "54", false);
check("triple(0n)", () => M.triple(0n), "0", false);
check("triple(1n)", () => M.triple(1n), "3", false);
check("triple(2n)", () => M.triple(2n), "6", false);
check("triple(5n)", () => M.triple(5n), "15", false);
check("triple(13n)", () => M.triple(13n), "39", false);
check("useTriple(0n)", () => M.useTriple(0n), "3", false);
check("useTriple(1n)", () => M.useTriple(1n), "9", false);
check("useTriple(2n)", () => M.useTriple(2n), "15", false);
check("useTriple(5n)", () => M.useTriple(5n), "33", false);
check("useTriple(13n)", () => M.useTriple(13n), "81", false);

console.log(`InlineDemo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
